import json,re
d=json.load(open("exegenius/tasks/0052-argument.answer.json"))
s=open("exegenius/tasks/0052-argument.answer.json").read()
def walk(n):
    yield n
    for c in n.get("children",[]) or []: yield from walk(c)
for n in walk(d["root"]):
    for k in ("claim","method","salient"):
        v=n.get(k)
        if v and re.search(r"[\t\n\r\x08\x0c]",v): print("CTRL",n["id"],k,repr(v)[:100])
    m=n.get("motivation")
    if m and re.search(r"[\t\n\r\x08\x0c]",m["text"]): print("CTRL mot",n["id"])
print(sum(1 for _ in walk(d["root"])))
EOF
